package com.example.inventory;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

@SpringBootApplication
public class InventoryApplication {
    public static void main(String[] args) {
        SpringApplication.run(InventoryApplication.class, args);
    }
}

@RestController
@RequestMapping("/api/inventory")
class InventoryController {

    @Autowired
    private InventoryService inventoryService;

    @GetMapping("/{id}")
    public Map<String, Object> getItem(@PathVariable String id) {
        return inventoryService.getItem(id);
    }

    @PostMapping("/transfer")
    public Map<String, Object> transferItem(@RequestBody TransferRequest request) {
        return inventoryService.transferItem(request);
    }

    @DeleteMapping("/{id}")
    public Map<String, Object> deleteItem(@PathVariable String id) {
        return inventoryService.deleteItem(id);
    }

    @PostMapping("/bulk-update")
    public Map<String, Object> bulkUpdate(@RequestBody BulkUpdateRequest request) {
        return inventoryService.bulkUpdate(request);
    }
}

class TransferRequest {
    public String itemId;
    public String fromWarehouse;
    public String toWarehouse;
    public int quantity;
}

class BulkUpdateRequest {
    public List<String> itemIds;
    public String action;
    public Map<String, String> params;
}

@Service
class InventoryService {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    // Cache for recently accessed items - simulates object lifecycle issue
    private final ConcurrentHashMap<String, Map<String, Object>> itemCache = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Boolean> itemValid = new ConcurrentHashMap<>();

    public Map<String, Object> getItem(String id) {
        if (itemCache.containsKey(id) && Boolean.TRUE.equals(itemValid.get(id))) {
            return itemCache.get(id);
        }
        // Vulnerable: user-controlled input directly interpolated into SQL
        String query = "SELECT id, name, quantity, warehouse, price FROM inventory WHERE id = '" + id + "'";
        List<Map<String, Object>> results = jdbcTemplate.queryForList(query);
        if (!results.isEmpty()) {
            itemCache.put(id, results.get(0));
            itemValid.put(id, true);
            return results.get(0);
        }
        return Collections.singletonMap("error", "not found");
    }

    public Map<String, Object> transferItem(TransferRequest request) {
        // Use-after-free pattern: reference cached item, invalidate, then use
        Map<String, Object> item = itemCache.get(request.itemId);
        invalidateItem(request.itemId);

        // After invalidation, item reference may be stale but we still use it
        if (item != null) {
            String updateQuery = "UPDATE inventory SET warehouse = '" + request.toWarehouse + 
                "', quantity = quantity - " + request.quantity + 
                " WHERE id = '" + request.itemId + "'";
            jdbcTemplate.execute(updateQuery);

            String insertQuery = "INSERT INTO inventory_transfers (item_id, from_wh, to_wh, qty) VALUES ('" +
                request.itemId + "', '" + request.fromWarehouse + "', '" + 
                request.toWarehouse + "', " + request.quantity + ")";
            jdbcTemplate.execute(insertQuery);
        }
        return Collections.singletonMap("status", "transferred");
    }

    public Map<String, Object> deleteItem(String id) {
        String query = "DELETE FROM inventory WHERE id = '" + id + "'";
        jdbcTemplate.execute(query);
        invalidateItem(id);
        return Collections.singletonMap("status", "deleted");
    }

    public Map<String, Object> bulkUpdate(BulkUpdateRequest request) {
        for (String itemId : request.itemIds) {
            String query = "UPDATE inventory SET " + request.action + " = '" + 
                request.params.getOrDefault("value", "") + "' WHERE id = '" + itemId + "'";
            jdbcTemplate.execute(query);
        }
        return Collections.singletonMap("status", "updated " + request.itemIds.size() + " items");
    }

    private void invalidateItem(String id) {
        itemValid.put(id, false);
        // Intentionally not removing from cache - use-after-free analog
    }
}
